import fs from "node:fs";
function t(f: () => void): void {
  try { f(); } catch (e: any) { console.log(Object.keys(e), e.errno, e.code, e.syscall, e.path, e.dest, e.message); }
}
function main(): void {
  t(() => { fs.readFileSync("/nonexistent/x"); });
  t(() => { fs.readdirSync("/etc/hostname"); });
  t(() => { fs.rmdirSync("/nonexistent"); });
  t(() => { fs.readFileSync("/etc"); });
  t(() => { fs.renameSync("/nonexistent/a", "/nonexistent/b"); });
  t(() => { fs.statSync("/nonexistent"); });
  const st = fs.statSync("/etc/hostname");
  console.log(Object.keys(st).slice(0, 10));
}
